  [Test] public void TryValidate_MapsOnlyTargetSubmeshAndRejectsStructureOrScopeChanges()
  {
   Mesh source=Mesh(); Mesh output=Object.Instantiate(source); var cell=new AtlasLayoutCell(new MaterialId("r","a"),0,0,0,256,256,0); var state=new AtlasMeshStructureOracle.MaterialState(new Vector4(1,1,0,0),new Vector4(1,1,0,0)); output.uv=new[]{AtlasUvTransform.Apply(source.uv[0],Vector2.one,Vector2.zero,cell,512),AtlasUvTransform.Apply(source.uv[1],Vector2.one,Vector2.zero,cell,512),AtlasUvTransform.Apply(source.uv[2],Vector2.one,Vector2.zero,cell,512),source.uv[3],source.uv[4],source.uv[5]}; var c=new[]{new AtlasMeshStructureOracle.Context(new MaterialId("r","a"),0,true,cell,512,Vector2.one,Vector2.zero,state,false,AtlasTextureSemantic.BaseColor),new AtlasMeshStructureOracle.Context(new MaterialId("r","b"),1,false,null,0,Vector2.one,Vector2.zero,state,true,AtlasTextureSemantic.Normal)};
   Assert.That(AtlasMeshStructureOracle.TryValidate(source,output,c,out var ok),Is.True,ok?.message); var changed=output.uv; changed[4]=new Vector2(.3f,.7f); output.uv=changed; Assert.That(AtlasMeshStructureOracle.TryValidate(source,output,c,out var scope),Is.False); Assert.That(scope.domainCode,Is.EqualTo("AtlasMeshStructureUvScope")); Object.DestroyImmediate(source);Object.DestroyImmediate(output);
  }
  [Test] public void TryValidate_RejectsInvalidContextAndSharedTargetVertex()
  {
