   var invalidSemantic=new[]{new AtlasMeshStructureOracle.Context(new MaterialId("r","a"),0,false,null,0,Vector2.one,Vector2.zero,false,(AtlasTextureSemantic)99),new AtlasMeshStructureOracle.Context(new MaterialId("r","b"),1,false,null,0,Vector2.one,Vector2.zero)}; Assert.That(AtlasMeshStructureOracle.TryValidate(source,output,invalidSemantic,out var semantic),Is.False); Assert.That(semantic.domainCode,Is.EqualTo("AtlasMeshStructureContextInvalid"));
