   output.bindposes=new[]{Matrix4x4.zero}; Assert.That(AtlasMeshStructureOracle.TryValidate(source,output,contexts,out var bind),Is.False); Assert.That(bind.domainCode,Is.EqualTo("AtlasMeshStructureBindposeChanged")); output.bindposes=source.bindposes; var changed=output.boneWeights; changed[0].weight0=.5f; output.boneWeights=changed; Assert.That(AtlasMeshStructureOracle.TryValidate(source,output,contexts,out var bone),Is.False); Assert.That(bone.domainCode,Is.EqualTo("AtlasMeshStructureBoneWeightChanged")); output.boneWeights=source.boneWeights; output.ClearBlendShapes(); Assert.That(AtlasMeshStructureOracle.TryValidate(source,output,contexts,out var blend),Is.False); Assert.That(blend.domainCode,Is.EqualTo("AtlasMeshStructureChanged")); Object.DestroyImmediate(source);Object.DestroyImmediate(output);
  }
