eForAtlasAcceptance(source,output,invalidExcluded,layout,state,state,out var excluded),Is.False); Assert.That(excluded.domainCode,Is.EqualTo("AtlasMeshStructureTargetExclusionMismatch")); Object.DestroyImmediate(source);Object.DestroyImmediate(output);
  }
