  [Test] public void TryValidateForAtlasAcceptance_RejectsSubmeshCountAndBlendShapeOrderChanges()
  {
   Mesh source=Mesh(); var zero=new Vector3[6]; source.AddBlendShapeFrame("a",100f,zero,zero,zero); source.AddBlendShapeFrame("b",100f,zero,zero,zero); var cell=new AtlasLayoutCell(new MaterialId("r","a"),0,0,0,256,256,0); var material=new AtlasMeshStructureOracle.MaterialState(new Vector4(1,1,0,0),new Vector4(1,1,0,0)); var contexts=new[]{new AtlasMeshStructureOracle.Context(new MaterialId("r","a"),0,true,cell,512,Vector2.one,Vector2.zero,material,false,AtlasTextureSemantic.BaseColor),new AtlasMeshStructureOracle.Context(new MaterialId("r","b"),1,false,null,0,Vector2.one,Vector2.zero,material,true,AtlasTextureSemantic.Normal)}; var layout=new AtlasLayoutResult(512,new[]{new AtlasSemanticPage(0,AtlasTextureSemantic.BaseColor,512),new AtlasSemanticPage(0,AtlasTextureSemantic.Normal,512)},new[]{cell}); var state=new AtlasMeshStructureOracle.RendererState(new[]{new MaterialId("r","a"),new MaterialId("r","b")},"root","avatar"); Mesh submeshChanged=Object.Instantiate(source); submeshChanged.subMeshCount=3; Assert.That(AtlasMeshStructureOracle.TryValidateForAtlasAcceptance(source,submeshChanged,contexts,layout,state,state,out var submesh),Is.False); Assert.That(submesh.domainCode,Is.EqualTo("AtlasMeshStructureChanged")); Mesh orderChanged=Object.Instantiate(source); orderChanged.ClearBlendShapes(); orderChanged.AddBlendShapeFrame("b",100f,zero,zero,zero); orderChanged.AddBlendShapeFrame("a",100f,zero,zero,zero); Assert.That(AtlasMeshStructureOracle.TryValidateForAtlasAcceptance(source,orderChanged,contexts,layout,state,state,out var order),Is.False); Assert.That(order.domainCode,Is.EqualTo("AtlasMeshStructureBlendShapeChanged")); Object.DestroyImmediate(source);Object.DestroyImmediate(submeshChanged);Object.DestroyImmediate(orderChanged);
  }
  static Mesh Mesh(){var m=new Mesh();m.vertices=new[]{Vector3.zero,Vector3.right,Vector3.up,new Vector3(2,0),new Vector3(3,0),new Vector3(2,1)};m.uv=new[]{Vector2.zero,Vector2.right,Vector2.up,Vector2.zero,Vector2.right,Vector2.up};m.subMeshCount=2;m.SetTriangles(new[]{0,1,2},0);m.SetTriangles(new[]{3,4,5},1);return m;}
 }
